+        builder.startObject().field("total", total).field("count", items.length).array("users", (Object[]) items);
+        return builder.endObject();
+    }
+
+    @Override
+    public String toString() {
+        return "QueryUsersResponse{" + "total=" + total + ", items=" + Arrays.toString(items) + '}';
